import{_ as a,o as i,c as t,a5 as s}from"./chunks/framework.UjrY2eRK.js";const u=JSON.parse('{"title":"Administration operations and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"operations/administration.md","filePath":"operations/administration.md","lastUpdated":1788228339000}'),r={name:"operations/administration.md"};function n(o,e,d,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="administration-operations-and-recovery" tabindex="-1">Administration operations and recovery <a class="header-anchor" href="#administration-operations-and-recovery" aria-label="Permalink to &quot;Administration operations and recovery&quot;">​</a></h1><p>The UI shows privacy-bounded operational data and fixed actions; it is not a general shell, database browser, identity manager, or configuration editor. Every mutation requires the exact public origin, a session-bound XSRF token, an audit intent that commits before execution, and a per-action lease, deadline, and cooldown.</p><h2 id="sessions-and-access" tabindex="-1">Sessions and access <a class="header-anchor" href="#sessions-and-access" aria-label="Permalink to &quot;Sessions and access&quot;">​</a></h2><p>Operator Sessions are local opaque records keyed by the OIDC issuer and subject. They have a 30-minute idle limit and an eight-hour absolute limit by default, with at most five sessions per identity and 100 per deployment. Provider access does not extend these limits. Removing a user from the required group prevents new sessions; revoke existing sessions from the Security page or purge all of them from a stopped one-off container:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host-admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.admin.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session-purge</span></span></code></pre></div><p>The command refuses disabled or invalid administration configuration. It does not contact the provider and does not create a recovery identity.</p><h2 id="operator-actions" tabindex="-1">Operator actions <a class="header-anchor" href="#operator-actions" aria-label="Permalink to &quot;Operator actions&quot;">​</a></h2><p>The Operations page exposes only:</p><ul><li><strong>Validate Firebase:</strong> performs an FCM <code>validate_only</code> request using a synthetic target. It proves credential, project, and API access, not that a mobile installation exists or will display a notification.</li><li><strong>Clean delivery state:</strong> applies the normal bounded retention cleanup to delivery records and budgets.</li><li><strong>Create gateway backup:</strong> writes and integrity-checks a new <code>gateway.sqlite</code> snapshot below <code>/data/backups</code>.</li></ul><p>Never retry an <code>outcome_unknown</code> action automatically: execution may have completed even though its final audit record failed. Review the audit page, backup directory, health, and redacted logs first. A busy or cooldown response should be allowed to expire rather than bypassed.</p><p>The operator API publishes one fixed mapping from every problem code to its HTTP status and safe title. Known cleanup and Firebase-validation results use only <code>succeeded</code> or <code>failed</code>; timeouts, busy leases, cooldowns, unknown finalization, backup limits, and administration unavailability remain explicit problem responses. The browser client and Bun response boundary are generated or validated from the same contract.</p><h2 id="metrics-and-audit-privacy" tabindex="-1">Metrics and audit privacy <a class="header-anchor" href="#metrics-and-audit-privacy" aria-label="Permalink to &quot;Metrics and audit privacy&quot;">​</a></h2><p>Metrics use only hourly/daily fixed-cardinality request, platform, outcome, and latency buckets. Metrics-writer startup, lock, corruption, or worker death drops new aggregates and never changes a Matrix response. Audit records contain the operator issuer/subject, action kind, coarse outcome, and finite reason; they do not contain provider tokens, client secrets, Matrix identifiers, Push Keys, account routes, or notification content.</p><p>The Metrics page requests a UTC half-open range. Omitting both endpoints selects the preceding 24 hours; supplying a range requires both endpoints in UTC, in order, and no more than 30 days apart. Only <code>hour</code> and <code>day</code> intervals are accepted. Duplicate or unknown query parameters are rejected rather than silently ignored.</p><p>Overview operation summaries expose only the gateway&#39;s finite safe reason vocabulary. Arbitrary provider, process, token, path, or request-derived values are rejected at the response boundary.</p><p>The defaults retain metrics for 30 days and audit entries for 90 days. Cleanup is bounded per pass. Treat <code>admin.sqlite</code>, browser sessions, audit data, and backups as sensitive operational metadata even though message content is never stored.</p><p>The Security page queries a UTC half-open range of at most 90 days. Its opaque load-older cursor fixes the initial range, filters, page size, timestamp, and identifier boundary; it is signed with the administration session secret and expires 15 minutes after the first page. Replaying it with the same filters is safe and deterministic. Changing any filter starts a new query; editing, reusing after expiry, or replaying the cursor with different filters is rejected.</p><h2 id="recover-from-an-identity-provider-outage" tabindex="-1">Recover from an identity-provider outage <a class="header-anchor" href="#recover-from-an-identity-provider-outage" aria-label="Permalink to &quot;Recover from an identity-provider outage&quot;">​</a></h2><p>Existing unexpired local sessions remain governed by local policy, while new login and provider logout may fail. Matrix delivery and public health must stay available. Restore the provider at the exact configured issuer; do not change the issuer temporarily because <code>(issuer, subject)</code> is the Operator Identity key.</p><p>If access must be revoked while the provider is unavailable:</p><ol><li>keep port 3000 private behind the TLS proxy;</li><li>disable the administration override or block <code>/admin/</code> at the proxy;</li><li>run <code>session-purge</code> with the valid administration configuration;</li><li>repair provider discovery, client credentials, callback URLs, and group mapping;</li><li>recreate the service and test member/non-member login before reopening the route.</li></ol><h2 id="recover-from-administration-storage-failure" tabindex="-1">Recover from administration storage failure <a class="header-anchor" href="#recover-from-administration-storage-failure" aria-label="Permalink to &quot;Recover from administration storage failure&quot;">​</a></h2><p>An <code>admin.sqlite</code> failure must not be repaired by pointing administration at <code>gateway.sqlite</code>; identical, symlinked, or hardlinked database files are rejected. Keep delivery running with administration disabled, restore the full volume or a separately protected administration database, then run the current image&#39;s <code>migrate</code> command before re-enabling. If the administration history is intentionally discarded, archive the failed files offline and allow the current image to create a fresh <code>admin.sqlite</code>; all previous sessions, audits, metrics, operation leases, and UI backup metadata are lost.</p><h2 id="routine-checks" tabindex="-1">Routine checks <a class="header-anchor" href="#routine-checks" aria-label="Permalink to &quot;Routine checks&quot;">​</a></h2><ul><li>Require public <code>/health</code> and an authenticated Overview to be ready.</li><li>Alert separately on Matrix failures and <code>/admin/*</code> failures.</li><li>Monitor <code>/data</code> capacity, both SQLite database families, and <code>/data/backups</code>.</li><li>Review sessions and audit outcomes after group, client, or secret changes.</li><li>Periodically prove a full-volume restore and the immediately preceding image&#39;s one-version rollback path.</li><li>Keep provider, reverse proxy, and gateway clocks synchronized.</li></ul><p>See <a href="/trinity-push-gateway/next/operations/troubleshooting.html">troubleshooting</a> for symptom-based checks.</p>`,26)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
